`,(0,n.jsx)(r.p,{children:"After finishing the course, you will have the opportunity to take a final assessment and earn a completion badge."}),`
`,(0,n.jsx)(r.h2,{id:"ai-diligence-statement",children:"AI diligence statement"}),`
`,(0,n.jsx)(r.p,{children:"In the development of the AI Fluency: Framework and Foundations course, we engaged in extensive collaboration with Claude 3.7 from Anthropic."}),`
